{"content":"import os
import re
import glob
import csv
from datetime import datetime

invoice_directory = "/protected/invoices/"
output_file = "/app/invoices_normalized.csv"

MONTHS = {
    'january': 1, 'february': 2, 'march': 3, 'april': 4,
    'may': 5, 'june': 6, 'july': 7, 'august': 8,
    'september': 9, 'october': 10, 'november': 11, 'december': 12,
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4,
    'jun': 6, 'jul': 7, 'aug': 8, 'sep': 9, 'sept': 9,
    'oct': 10, 'nov': 11, 'dec': 12,
}

def normalize_date(raw):
    s = raw.strip().strip('.').strip()
    # MM/DD/YYYY
    m = re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})$', s)
    if m:
        mm, dd, yyyy = map(int, m.groups())
        return f"{yyyy:04d}-{mm:02d}-{dd:02d}"
    # DD-MM-YYYY (per task spec, dash form is DD-MM-YYYY)
    m = re.match(r'^(\d{1,2})-(\d{1,2})-(\d{4})$', s)
    if m:
        dd, mm, yyyy = map(int, m.groups())
        # Fallback safety: if first part > 12 treat as day, if second > 12 treat as swapped
        # but spec says dash = DD-MM, so keep that unless invalid
        if mm > 12 and dd <= 12:
            dd, mm = mm, dd
        return f"{yyyy:04d}-{mm:02d}-{dd:02d}"
    # ISO already
    m = re.match(r'^(\d{4})-(\d{2})-(\d{2})$', s)
    if m:
        return s
    # Text date: April 10, 2024 / Apr 10 2024 / 10 April 2024
    m = re.match(r'^([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})$', s)
    if m:
        mon = MONTHS.get(m.group(1).lower())
        if mon:
            return f"{int(m.group(3)):04d}-{mon:02d}-{int(m.group(2)):02d}"
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]+),?\s+(\d{4})$', s)
    if m:
        mon = MONTHS.get(m.group(2).lower())
        if mon:
            return f"{int(m.group(3)):04d}-{mon:02d}-{int(m.group(1)):02d}"
    # Fallback via dateutil if available
    try:
        from dateutil import parser as dparser
        dayfirst = '-' in s  # dash-style dates default day-first
        dt = dparser.parse(s, dayfirst=dayfirst)
        return dt.strftime('%Y-%m-%d')
    except Exception:
        pass
    # Last resort: try common strptime variants
    for fmt, out in [('%m/%d/%Y', True), ('%d-%m-%Y', True), ('%B %d, %Y', True), ('%b %d, %Y', True)]:
        try:
            return datetime.strptime(s, fmt).strftime('%Y-%m-%d')
        except Exception:
            continue
    return s

def extract_invoice_number(text):
    m = re.search(r'Invoice\s*(?:Number|#|No\.?|Num)?\s*[:#]\s*([A-Za-z0-9][A-Za-z0-9\-\_/]*)', text, re.IGNORECASE)
    if m:
        return m.group(1).strip().rstrip('.,;:')
    return ''

def extract_date_raw(text):
    m = re.search(r'Invoice\s*Date\s*:\s*(.+?)(?:\n|$)', text, re.IGNORECASE)
    if m:
        return m.group(1).strip()
    m = re.search(r'(?<!\w)Date\s*:\s*(.+?)(?:\n|$)', text, re.IGNORECASE)
    if m:
        return m.group(1).strip()
    return ''

def extract_vendor(text):
    lines = [l.strip() for l in text.splitlines()]
    vendor_name = ''
    vendor_addr_line = ''
    for i, ln in enumerate(lines):
        low = ln.lower()
        inline = None
        if re.match(r'^\s*(bill\s*from|vendor|from)\s*:\s*\S+', ln, re.IGNORECASE):
            # e.g. "Vendor: Acme Corp"
            inline = re.sub(r'^\s*(bill\s*from|vendor|from)\s*:\s*', '', ln, flags=re.IGNORECASE).strip()
            if inline:
                vendor_name = inline
                # address is next non-empty line
                for j in range(i+1, len(lines)):
                    if lines[j]:
                        vendor_addr_line = lines[j]
                        break
                break
            continue
        if re.match(r'^\s*(bill\s*from|vendor)\s*:?\s*$', ln, re.IGNORECASE):
            # next non-empty line = vendor name, following = address
            nxt = []
            for j in range(i+1, len(lines)):
                if lines[j]:
                    nxt.append(lines[j])
                if len(nxt) >= 2:
                    break
            if len(nxt) >= 1:
                vendor_name = nxt[0]
            if len(nxt) >= 2:
                vendor_addr_line = nxt[1]
            break
    return vendor_name, vendor_addr_line

def parse_address(addr_line):
    street = addr_line.strip()
    city = ''
    postal = ''
    if not addr_line:
        return street, city, postal
    m = re.match(r'(.+?),\s*([^,]+?),\s*[A-Za-z]{2}\s+(\d{5}(?:-\d{4})?)', addr_line.strip())
    if m:
        return m.group(1).strip(), m.group(2).strip(), m.group(3).strip()
    # fallback: zip is last 5-digit token
    zm = re.search(r'(\d{5}(?:-\d{4})?)\s*$', addr_line.strip())
    if zm:
        postal = zm.group(1)
    # city: token between commas
    parts = [p.strip() for p in addr_line.split(',')]
    if len(parts) >= 2:
        # city is second-to-last or middle part stripped of state+zip
        city_part = parts[-2] if len(parts) >= 2 else ''
        city = re.sub(r'\s+[A-Za-z]{2}\s+\d.*$', '', city_part).strip()
        city = re.sub(r'\s+[A-Za-z]{2}$', '', city).strip()
        street = parts[0].strip()
    return street, city, postal

def extract_items(text):
    lines = text.splitlines()
    # find items header
    start = None
    for i, ln in enumerate(lines):
        if re.match(r'^\s*(line\s*items|items|order\s*details|item\s*details|description)\s*:?\s*$', ln, re.IGNORECASE):
            start = i + 1
            break
    candidate_lines = lines[start:] if start is not None else lines
    amounts = []
    for ln in candidate_lines:
        if not ln.strip():
            continue
        # skip explicit totals/balance lines (they are not distinct items)
        if re.search(r'\b(grand\s*total|invoice\s*total|total\s*due|balance\s*due|amount\s*due)\b', ln, re.IGNORECASE):
            continue
        # line-item pattern: something - $X.XX  (also handles "x2", ":", etc.)
        # Require a $ amount on the line; treat each such line as one item
        # but skip a bare "Total: $X" line
        if re.search(r'^\s*total\b', ln.strip(), re.IGNORECASE) and len(amounts) >= 0:
            # A line starting with Total/Subtotal/Tax/Shipping IS an item per this task's data
            # (invoice_003 lists Shipping and Tax as items). Only skip grand totals above.
            pass
        m = re.search(r'\$\s*([\d,]+\.\d{1,2})', ln)
        if m:
            try:
                val = float(m.group(1).replace(',', ''))
                amounts.append(val)
            except ValueError:
                continue
    return amounts

def vendor_id_for(vendor_name, postal):
    letters = re.sub(r'[^A-Za-z]', '', vendor_name or '')
    prefix = (letters[:3].upper() + 'XXX')[:3]
    digits = re.sub(r'\D', '', postal or '')
    suffix = digits[-4:] if len(digits) >= 4 else digits.zfill(4)
    return prefix + suffix

def process_pdf(path):
    import pdfplumber
    with pdfplumber.open(path) as pdf:
        text = '\n'.join([(p.extract_text() or '') for p in pdf.pages])
    inv = extract_invoice_number(text)
    raw_date = extract_date_raw(text)
    iso_date = normalize_date(raw_date) if raw_date else ''
    vname, addr_line = extract_vendor(text)
    street, city, postal = parse_address(addr_line)
    amounts = extract_items(text)
    total = round(sum(amounts), 2)
    count = len(amounts)
    vid = vendor_id_for(vname, postal)
    return {
        'invoice_number': inv,
        'invoice_date': iso_date,
        'vendor_name': vname,
        'vendor_address': street,
        'city': city,
        'postal_code': postal,
        'total_amount': f"{total:.2f}",
        'vendor_id': vid,
        'item_count': str(count),
    }

def main():
    files = sorted(glob.glob(os.path.join(invoice_directory, '*.pdf')))
    rows = [process_pdf(f) for f in files]
    # deterministic order by invoice_number
    rows.sort(key=lambda r: r['invoice_number'])
    cols = ['invoice_number', 'invoice_date', 'vendor_name', 'vendor_address', 'city', 'postal_code', 'total_amount', 'vendor_id', 'item_count']
    with open(output_file, 'w', newline='', encoding='utf-8') as fh:
        w = csv.DictWriter(fh, fieldnames=cols)
        w.writeheader()
        w.writerows(rows)
    print(f"Wrote {len(rows)} rows to {output_file}")
    for r in rows:
        print(r)

if __name__ == '__main__':
    main()
